/* Abremi service worker
 * - The app shell (HTML, scripts, styles, icons) is precached, so Abremi opens offline.
 * - Each deploy gets a new VERSION, so updates are never stuck behind a stale cache;
 *   the page offers a "Refresh" prompt when a new version is waiting.
 * - Live data and sign-in (Supabase) always go to the network and are never cached.
 */

// ——— generated by scripts/gen-sw.js — do not edit between these markers ———
const VERSION = '59fdadd54771';
const ASSETS = [
  "./",
  "./index.html",
  "./manifest.webmanifest",
  "./src/config.js",
  "./src/core/badges.js",
  "./src/core/community.js",
  "./src/core/elo.js",
  "./src/core/feed.js",
  "./src/core/marketplace.js",
  "./src/core/random.js",
  "./src/core/rankings.js",
  "./src/core/recognition.js",
  "./src/core/scoring.js",
  "./src/core/seed.js",
  "./src/core/world.js",
  "./src/ui/app.js",
  "./src/ui/art.js",
  "./src/ui/cloud.js",
  "./src/ui/components.js",
  "./src/ui/pwa.js",
  "./src/ui/store.js",
  "./src/ui/styles.css",
  "./icons/apple-touch-icon.png",
  "./icons/favicon-32.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/icon-maskable-512.png"
];
// ——— end generated ———

const SHELL = `abremi-shell-${VERSION}`;
const RUNTIME = 'abremi-runtime-v1';
const RUNTIME_HOSTS = ['fonts.googleapis.com', 'fonts.gstatic.com', 'cdn.jsdelivr.net'];
const PAGE_TIMEOUT_MS = 4000;

// The app moved from gabangi.vercel.app to abremi.vercel.app. On the old address this worker
// retires: it clears its caches, removes itself and reloads open pages, so the server's
// redirect can take visitors to the new address instead of a stale offline copy.
const RETIRED_HOSTS = ['gabangi.vercel.app'];

if (RETIRED_HOSTS.includes(self.location.hostname)) {
  self.addEventListener('install', () => self.skipWaiting());
  self.addEventListener('activate', (event) => {
    event.waitUntil((async () => {
      await Promise.all((await caches.keys()).map((k) => caches.delete(k)));
      await self.registration.unregister();
      const pages = await self.clients.matchAll({ type: 'window' });
      await Promise.all(pages.map((page) => page.navigate(page.url).catch(() => {})));
    })());
  });
} else {
  self.addEventListener('install', (event) => {
    event.waitUntil(caches.open(SHELL).then((cache) => cache.addAll(ASSETS.map((url) => new Request(url, { cache: 'reload' })))));
  });

  self.addEventListener('activate', (event) => {
    event.waitUntil((async () => {
      const keys = await caches.keys();
      // Old versions, plus caches from before the rename to Abremi.
      const stale = (k) => (k.startsWith('abremi-shell-') && k !== SHELL) || k.startsWith('gabangi-');
      await Promise.all(keys.filter(stale).map((k) => caches.delete(k)));
      await self.clients.claim();
    })());
  });

  self.addEventListener('message', (event) => {
    if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
  });

  self.addEventListener('fetch', (event) => {
    const { request } = event;
    if (request.method !== 'GET') return;
    const url = new URL(request.url);
    if (url.hostname.endsWith('.supabase.co') || url.hostname.endsWith('.supabase.in')) return; // live data: network only
    if (request.mode === 'navigate') return event.respondWith(page(request));
    if (url.origin === self.location.origin) return event.respondWith(shell(request));
    if (RUNTIME_HOSTS.includes(url.hostname)) return event.respondWith(staleWhileRevalidate(request));
  });
}

/** Pages: fresh from the network when possible, the cached app when offline or slow. */
async function page(request) {
  try {
    const response = await Promise.race([
      fetch(request),
      new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), PAGE_TIMEOUT_MS)),
    ]);
    if (response.ok) return response;
    throw new Error(`HTTP ${response.status}`);
  } catch {
    const cache = await caches.open(SHELL);
    return (await cache.match('./', { ignoreSearch: true })) || (await cache.match('./index.html', { ignoreSearch: true })) || Response.error();
  }
}

/** Own files: from this version's cache, falling back to the network. */
async function shell(request) {
  const cached = await caches.match(request, { cacheName: SHELL, ignoreSearch: true });
  return cached || fetch(request);
}

/** Fonts and the database client library: instant from cache, refreshed in the background. */
async function staleWhileRevalidate(request) {
  const cache = await caches.open(RUNTIME);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response.ok || response.type === 'opaque') cache.put(request, response.clone());
      return response;
    })
    .catch(() => cached || Response.error());
  return cached || network;
}
